python3 -c "
import re, json
p = '/home/user/myproject/chart.html'
with open(p) as f:
    html = f.read()
m = re.search(r'const spec = (\{.*?\});\s*\n', html, re.DOTALL)
if m:
    spec = json.loads(m.group(1))
    print('Spec parsed OK')
    print('Top-level keys:', list(spec.keys()))
    def walk(s, depth=0):
        if isinstance(s, dict):
            if 'vconcat' in s:
                print('  '*depth + 'vconcat ['+str(len(s['vconcat']))+']')
                for c in s['vconcat']:
                    walk(c, depth+1)
            elif 'hconcat' in s:
                print('  '*depth + 'hconcat ['+str(len(s['hconcat']))+']')
                for c in s['hconcat']:
                    walk(c, depth+1)
            elif 'mark' in s:
                params = s.get('params', [])
                sel_names = [p2.get('name','?') for p2 in params if isinstance(p2,dict) and p2.get('name')]
                tfs = s.get('transform', [])
                print('  '*depth + 'mark=' + str(s.get('mark')) + ' selections=' + str(sel_names) + ' ntransforms=' + str(len(tfs)))
            else:
                print('  '*depth + 'dict keys: ' + str(list(s.keys())[:6]))
    walk(spec)
else:
    print('Could not extract spec')
"

